const box = {
  n: 1,
  show() {
    console.log(this.n);
  },
};
box.show();

function show() {
  console.log(this.n);
}
const a = { n: 1, show };
const b = { n: 2, show };
a.show();
b.show();

'use strict';
const box = {
  n: 1,
  show() {
    console.log(this.n);
  },
};
function run(fn) {
  try {
    fn();
  } catch {
    console.log(2);
  }
}
run(box.show);
run(() => box.show());

function show() {
  console.log(this.n);
}
show.call({ n: 1 });
show.call({ n: 2 });

const box = {
  n: 1,
  show() {
    console.log(this.n);
  },
};
const show = box.show.bind({ n: 2 });
show();
box.show();

const box = {
  n: 1,
  show() {
    const inner = {
      n: 2,
      read: () => console.log(this.n),
    };
    inner.read();
  },
};
box.show();

const box = {
  n: 1,
  show() {
    const self = this;
    function inner() {
      console.log(self.n);
      console.log(this.n);
    }
    inner.call({ n: 2 });
  },
};
box.show();

function Box(n) {
  this.n = n;
}
console.log(new Box(1).n);
console.log(new Box(2).n);
